class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        maxleft = SortedDict()
        n = len(nums)

        for i in range(n):
            if nums[i] in maxleft:
                continue
            else:
                previdx = maxleft.bisect_left(nums[i]) - 1
                if previdx == -1:
                    maxleft[nums[i]] = nums[i]
                else:
                    if previdx >= 0:
                        maxleft[nums[i]] = max(maxleft[nums[i]], maxleft.peekitem(previdx)[1] + nums[i])

            nextidx = maxleft.bisect_right(nums[i])
            if nextidx < len(maxleft.keys()) and maxleft.peekitem(nextidx)[1] <= maxleft[nums[i]]:
                del maxleft[maxleft.peekitem(nextidx)[0]]

        return max(maxleft.values())

