        count = 0

        # Step 10: For `i` in the range of the length of `s`:
        for i in range(len(s)):
            # Update `cursum`:
            if s[i] in vowels:
                cursum += 1  # Increment if `s[i]` is a vowel.
            else:
                cursum -= 1  # Decrement if `s[i]` is a consonant.

            # Set `cate` to `i % p`.
